#!/usr/bin/env bash
main_menu(){ while true; do title "Termux Hardware Dashboard v$APP_VERSION"; echo "$MSG_SUBTITLE"; echo "1) $MSG_OVERVIEW"; echo "2) $MSG_CPU"; echo "3) $MSG_GPU"; echo "4) $MSG_MEMORY"; echo "5) $MSG_STORAGE"; echo "6) $MSG_BATTERY"; echo "7) $MSG_DISPLAY"; echo "8) $MSG_SYSTEM"; echo "9) $MSG_SENSORS"; echo "10) $MSG_NETWORK"; echo "11) $MSG_DIAG"; echo "12) $MSG_SETTINGS"; echo "0) $MSG_EXIT"; read -r -p "$MSG_CHOICE " c; case "$c" in 1) title "$MSG_OVERVIEW"; show_system; show_cpu; show_memory; show_battery; pause;; 2) section "$MSG_CPU" show_cpu;; 3) section "$MSG_GPU" show_gpu;; 4) section "$MSG_MEMORY" show_memory;; 5) section "$MSG_STORAGE" show_storage;; 6) section "$MSG_BATTERY" show_battery;; 7) section "$MSG_DISPLAY" show_display;; 8) section "$MSG_SYSTEM" show_system;; 9) section "$MSG_SENSORS" show_sensors;; 10) section "$MSG_NETWORK" show_network;; 11) section "$MSG_DIAG" diagnostics;; 12) settings_menu;; 0|q|Q) break;; *) echo "$MSG_INVALID"; sleep 1;; esac; done; }
settings_menu(){ title "$MSG_SETTINGS"; echo "1) Tiếng Việt  2) English  0) Back"; read -r -p "$MSG_CHOICE " c; case "$c" in 1) echo vi > "$HOME/.config/termux-hardware-dashboard/lang";; 2) echo en > "$HOME/.config/termux-hardware-dashboard/lang";; esac; }
